package com.mylittleblover.mkwplayer.graph

import kotlin.test.Test
import kotlin.test.assertContentEquals
import kotlin.test.assertEquals
import kotlin.test.assertTrue

/**
 * Compares this builder against the Python builder that produced the graph the
 * device tests actually play.
 *
 * Two independent implementations of one wire format agreeing byte for byte is
 * the strongest check available without a device: if either drifted, the bytes
 * would differ. The committed fixture is not a copy of the Kotlin output -- it was
 * generated by `tools/graph_build.py` and has already been accepted and played by
 * the native engine on the emulator.
 */
class GraphBuilderMatchesReferenceTest {

    private fun fixture(): ByteArray {
        val text = javaClass.classLoader!!
            .getResourceAsStream("mkw-coaster-graph-v6.hex")
            ?.bufferedReader()?.readText()
            ?: error("mkw-coaster-graph-v6.hex missing from test resources")
        return text.trim().chunked(2).map { it.toInt(16).toByte() }.toByteArray()
    }

    /** The same parameters the fixture was generated with. */
    private fun spec() = GraphBuilder.Spec(
        asset = GraphBuilder.Asset(
            path = "BGM_Stage_Coaster.bwav",
            sampleRate = 48000,
            channels = 2,
            frames = 3_373_711,
            sha256 = "6bb12e5329eb01b14e0bb8672b8be178d3e003cc922aa2ef17d95a598ab7595b"
                .chunked(2).map { it.toInt(16).toByte() }.toByteArray(),
            loop = GraphBuilder.Loop(startFrame = 493_714, endFrame = 3_373_711, count = -1),
        ),
    )

    @Test
    fun kotlinBuilderReproducesThePythonFixtureExactly() {
        val expected = fixture()
        val actual = GraphBuilder.build(spec())

        assertEquals(expected.size, actual.size, "packet length differs")

        val firstDiff = (expected.indices).firstOrNull { expected[it] != actual[it] }
        assertTrue(
            firstDiff == null,
            "packets differ at byte $firstDiff: expected 0x%02x, got 0x%02x".format(
                firstDiff?.let { expected[it].toInt() and 0xFF } ?: 0,
                firstDiff?.let { actual[it].toInt() and 0xFF } ?: 0,
            ),
        )
        assertContentEquals(expected, actual)
    }

    @Test
    fun theFixtureIsTheVersionThisBuilderEmits() {
        val result = GraphProbe.inspect(fixture())
        assertTrue(result is GraphProbe.Result.Ok)
        assertEquals(GraphBuilder.VERSION, (result as GraphProbe.Result.Ok).version)
    }
}
